import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const n="/llamatron/assets/wizard_genre.CpDR6vRE.svg",r="/llamatron/assets/wizard_band.Bft3RoyP.svg",h="/llamatron/assets/wizard_player.C5ixWqdD.svg",i="/llamatron/assets/wizard_chords.BSqm11Qq.svg",d="/llamatron/assets/wizard_melody.Jrrar986.svg",l="/llamatron/assets/wizard_tunes.DO8eTTpG.svg",p="/llamatron/assets/wizard_hooks.DmGsT2uE.svg",c="/llamatron/assets/wizard_form.oRo9b04u.svg",m="/llamatron/assets/wizard_section.DKrO6Wkw.svg",g="/llamatron/assets/wizard_apply.C8TiZZRO.svg",z=JSON.parse('{"title":"Song Wizard","description":"","frontmatter":{},"headers":[],"relativePath":"WIZARD.md","filePath":"WIZARD.md"}'),w={name:"WIZARD.md"};function u(y,e,f,b,k,_){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="song-wizard" tabindex="-1">Song Wizard <a class="header-anchor" href="#song-wizard" aria-label="Permalink to &quot;Song Wizard&quot;">​</a></h1><p>The song wizard makes a whole song from a few choices: a genre, a band, chords, tunes and a form. A songwriter starts the same way, deciding what kind of song it is, who plays, what the chords are and which section follows which, before anyone plays a note. The wizard asks for those decisions and writes the patterns, tracks, scenes and clips that a band of that genre would play, and the result is an ordinary song of the set, every note of which can be edited afterwards on Arrange and in the pattern editor.</p><p><code>F5</code> opens the wizard from any page. Nothing in the set changes until Apply, and undo then takes the whole song away again. Each run makes a different song from the same choices.</p><p>The wizard is in progress: its panels change from one version to the next, and this page shows what each panel holds now. How to work through a song with the wizard will get a page of its own.</p><h2 id="wizard-layout" tabindex="-1">Wizard Layout <a class="header-anchor" href="#wizard-layout" aria-label="Permalink to &quot;Wizard Layout&quot;">​</a></h2><p>The tree at the left lists the wizard&#39;s panels, and the settings of the panel under the cursor show at the right. Up and Down move through the tree, Left and Right close and open a panel that has panels under it, <code>ENTER</code> or Tab moves into the settings, and <code>ESC</code> or Tab moves back to the tree. <code>L</code> (listen) plays what the panel under the cursor would make, a tune, a hook, a player or a section, through FluidSynth. <code>ESC</code> in the tree closes the wizard, and asks first.</p><h2 id="genre" tabindex="-1">Genre <a class="header-anchor" href="#genre" aria-label="Permalink to &quot;Genre&quot;">​</a></h2><p>The Genre panel comes first, since every other panel starts from what the genre usually does. Choosing a genre and, under Genre in the tree, a subgenre fills in the key, the scale, the tempo, the meter, the band and the form with what that kind of song usually has. Each can then be changed, and the panel shows how long the song will play.</p><p><img src="'+n+'" alt="The song wizard&#39;s Genre panel"></p><h2 id="band" tabindex="-1">Band <a class="header-anchor" href="#band" aria-label="Permalink to &quot;Band&quot;">​</a></h2><p>The Band panel chooses who is in the band. Each player is switched in or out, Sounds chooses the band&#39;s set of instrument sounds, Guitarists chooses one guitar or two, Tune played by names the player who carries the tune, and Answered by names the player who answers the tune in the gaps between its lines.</p><p><img src="'+r+'" alt="The song wizard&#39;s Band panel"></p><h2 id="players" tabindex="-1">Players <a class="header-anchor" href="#players" aria-label="Permalink to &quot;Players&quot;">​</a></h2><p>Each player in the band has a panel under Band in the tree. Plays chooses the kind of part the player plays, such as a chiming arpeggio or strummed chords, and Sound the instrument. Comes in and Lays out say when the player joins the song and when the player rests, as a real player waits for the second verse or drops out before a chorus. Reacts and Dynamics set how much the player follows the rest of the band and the song&#39;s louds and softs, and the gauges below them set how busy and how varied the part is.</p><p><img src="'+h+'" alt="The panel of one player, the rhythm guitar"></p><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p>Composition holds the panels of what the song is made of: its chords, its melody style, its tunes and its hook.</p><h3 id="chords" tabindex="-1">Chords <a class="header-anchor" href="#chords" aria-label="Permalink to &quot;Chords&quot;">​</a></h3><p>The Chords panel chooses the chord progression: one of the genre&#39;s progressions by name, or any, which leaves the choice to the wizard when the song is made.</p><p><img src="'+i+'" alt="The song wizard&#39;s Chords panel"></p><h3 id="melody" tabindex="-1">Melody <a class="header-anchor" href="#melody" aria-label="Permalink to &quot;Melody&quot;">​</a></h3><p>The Melody panel chooses the style the tunes are written in, such as a walk by steps or a tune of leaps, and how the tune is phrased: how long its lines are, how long the breath after a line is, and how often a line starts early.</p><p><img src="'+d+'" alt="The song wizard&#39;s Melody panel"></p><h3 id="tunes" tabindex="-1">Tunes <a class="header-anchor" href="#tunes" aria-label="Permalink to &quot;Tunes&quot;">​</a></h3><p>The Tunes panel lists the tune of each kind of section, one for the verses and one for the choruses, so that every verse plays the same tune as verses do. <code>ENTER</code> (edit notes) on a tune opens the tune in the pattern editor, where the notes are edited as any pattern&#39;s are, and <code>ESC</code> there comes back to the wizard. A tune that was edited is marked <code>(edited)</code>, belongs to the person from then on, and is never written over by another choice; <code>Bksp</code> gives the tune back to the wizard.</p><p><img src="'+l+'" alt="The song wizard&#39;s Tunes panel"></p><h3 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h3><p>The Hooks panel switches the song&#39;s hook on, the short phrase a listener goes away humming, and shows the hook&#39;s notes. Its sections choose the hook&#39;s kind, where in the song the hook is said, and the riff, a short figure a player repeats under the song. New hook draws another.</p><p><img src="'+p+'" alt="The song wizard&#39;s Hooks panel"></p><h2 id="form" tabindex="-1">Form <a class="header-anchor" href="#form" aria-label="Permalink to &quot;Form&quot;">​</a></h2><p>The Form panel chooses the sections the song plays and in what order. Song plan gives every section a place in a rise and fall across the whole song, Contrast sets how far the loud sections stand from the quiet ones, and Starts with and Ends with choose how the song begins and ends. The list at the bottom says what the plan gives each section.</p><p><img src="'+c+'" alt="The song wizard&#39;s Form panel"></p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><p>Each section has a panel under Form in the tree. On a section, <code>I</code> (insert) adds a section before it, <code>A</code> (add) adds one at the end, <code>C</code> (copy) copies it, <code>Bksp</code> (delete) removes it and <code>M</code> (move) carries it to another place. The section&#39;s settings choose its kind, how many bars it lasts and its energy, and its headings open the section&#39;s tune, harmony, shape, the way it joins the section after it, and who plays in it.</p><p><img src="'+m+'" alt="The panel of one section, the first verse"></p><h2 id="apply" tabindex="-1">Apply <a class="header-anchor" href="#apply" aria-label="Permalink to &quot;Apply&quot;">​</a></h2><p>The Apply panel sums the song up, its genre, key, tempo, form and length, and <code>ENTER</code> on the Apply button makes the song and shows it on <a href="./ARRANGE">Arrange</a>.</p><p><img src="'+g+'" alt="The song wizard&#39;s Apply panel"></p>',38)])])}const v=a(w,[["render",u]]);export{z as __pageData,v as default};
